// The bundled gitleaks rules (spec, Secret scan, "Bundled gitleaks rules").
// `src/rules/gitleaks.json` is generated by `scripts/build-secret-rules.mts`
// from gitleaks `config/gitleaks.toml` at a pinned tag and sha256, and
// committed; never edit it by hand. The scan that uses the rules is Step 7.
import rulesJson from './gitleaks.json'

/** A Go RE2 pattern converted for `new RegExp(source, flags)`. */
export type ConvertedRegex = { source: string; flags: string }

/**
 * One rule allowlist. `regexTarget` is what `regexes` test: the secret group,
 * the whole match, or the line of the match. `stopwords` are case-insensitive
 * substrings of the secret. `paths` is present only with `condition: "AND"`,
 * where it narrows the allowlist to those files.
 */
export type BundledAllowlist = {
  condition: 'OR' | 'AND'
  regexTarget: 'secret' | 'match' | 'line'
  regexes: ConvertedRegex[]
  stopwords: string[]
  paths?: ConvertedRegex[]
}

export type BundledRule = {
  id: string
  /** null for a path-only rule (for example `pkcs12-file`): the path alone is the finding. */
  regex: ConvertedRegex | null
  /** The capture group that holds the secret; 0 when the rule does not set one. */
  secretGroup: number
  /** Minimum Shannon entropy of the secret, or null for no check. */
  entropy: number | null
  /** Case-insensitive prefilter: the rule runs only on text that has one of them. */
  keywords: string[]
  /** The rule applies only to files whose path matches. */
  path: ConvertedRegex | null
  allowlists: BundledAllowlist[]
}

/** Where the rules come from: the gitleaks tag and the sha256 of its config file. */
export type RulesSource = { name: 'gitleaks'; tag: string; path: string; sha256: string }

export type SkippedRule = { id: string; reason: string }

export type BundledRules = {
  schema: 1
  source: RulesSource
  /** The number of bundled rules. */
  count: number
  /** Rules of the source left out, each with its reason (`scripts/secret-rules-skipped.json`). */
  skipped: SkippedRule[]
  rules: BundledRule[]
}

export const bundledRules = rulesJson as BundledRules

/** `report.tool.rules`: `{source, count, skipped}`. */
export type RulesSummary = { source: RulesSource; count: number; skipped: SkippedRule[] }

export function rulesSummary(rules: BundledRules = bundledRules): RulesSummary {
  return {
    source: { ...rules.source },
    count: rules.count,
    skipped: rules.skipped.map((entry) => ({ id: entry.id, reason: entry.reason })),
  }
}
